// Notifications from both sources: the profile's local notifications (DataSource, both modes)
// and, in connected mode, the server's (budget alerts, reminders generated by the API job).
import type * as D from '@finplat/domain';
import { useMutation, useQuery } from '@tanstack/react-query';
import { useEffect } from 'react';
import { qk, useData, useFinance, useInvalidate } from '../app/data.tsx';
import { BROWSER_SETTING } from '../features/notifications/useNotifications.ts';
import { isNative, nativeNotify } from '../platform/native.ts';

// Native app (no Web Push): server notifications first seen while the app runs become OS
// notifications. The first poll only records what is already there.
const shown = new Set<string>();
let primed = false;

export type AppNotification = D.Notification & { origin: 'local' | 'server' };

export function useNotifications() {
  const ops = useFinance();
  const { api, profile } = useData();
  const q = useQuery({
    queryKey: qk(profile?.id ?? '', 'notifications', !!api),
    refetchInterval: 60_000,
    queryFn: async (): Promise<AppNotification[]> => {
      const local = (await ops.listNotifications()).map((n) => ({
        ...n,
        origin: 'local' as const,
      }));
      let server: AppNotification[] = [];
      if (api)
        server = await api
          .request<{ items: D.Notification[] }>('GET', '/api/v1/notifications?limit=100')
          .then((r) =>
            r.items
              .filter((n) => !n.profileId || n.profileId === profile?.id)
              .map((n) => ({ ...n, origin: 'server' as const })),
          )
          .catch(() => []); // offline: local ones still show
      return [...local, ...server].sort((a, b) => b.createdAt.localeCompare(a.createdAt));
    },
  });
  const settings = useQuery({
    queryKey: qk(profile?.id ?? '', 'notification-setting'),
    enabled: isNative,
    queryFn: async () => (await ops.getSettings())[BROWSER_SETTING] === true,
  });
  useEffect(() => {
    if (!isNative || !q.data) return;
    const fresh = q.data.filter((n) => n.origin === 'server' && !n.readAt && !shown.has(n.id));
    for (const n of fresh) shown.add(n.id);
    if (primed && settings.data === true)
      for (const n of fresh.slice(0, 5)) void nativeNotify(n.title, n.body);
    primed = true;
  }, [q.data, settings.data]);
  return q;
}

export function useMarkRead() {
  const ops = useFinance();
  const { api } = useData();
  const invalidate = useInvalidate();
  return useMutation({
    mutationFn: async (n?: AppNotification) => {
      if (!n) {
        await ops.markNotificationRead();
        if (api) await api.request('POST', '/api/v1/notifications/read-all');
      } else if (n.origin === 'local') await ops.markNotificationRead(n.id);
      else await api?.request('POST', `/api/v1/notifications/${n.id}/read`);
    },
    onSuccess: () => invalidate(),
  });
}
